 "content": "def transform(grid):
    """Project each 3-ring along its supporting 2-rail, marking crossings."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    original = [row[:] for row in grid]
    threshold = 0.70
    row_rails = [r for r in range(h) if sum(v == 2 for v in original[r]) / w >= threshold]
    col_rails = [c for c in range(w) if sum(original[r][c] == 2 for r in range(h)) / h >= threshold]

    # A source is the 3x3 ring around a 2 center, centered on a strong rail.
    sources = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if original[r][c] != 2:
                continue
            ring = [(r + dr, c + dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1) if (dr, dc) != (0, 0)]
            if all(original[rr][cc] == 3 for rr, cc in ring):
                if c in col_rails and r not in row_rails:
                    sources.append((r, c, 'h'))
                elif r in row_rails and c not in col_rails:
                    sources.append((r, c, 'v'))

    for r, c, direction in sources:
        if direction == 'h':
            # Project horizontally; 2-rails receive a 1-colored ring at each crossing.
            for cc in range(w):
                if g[r][cc] == 0:
                    g[r][cc] = 1
            for target_c in col_rails:
                if target_c == c:
                    continue
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        rr, cc = r + dr, target_c + dc
                        if 0 <= rr < h and 0 <= cc < w and (dr, dc) != (0, 0):
                            g[rr][cc] = 1
        else:
            # Project vertically; horizontal 2-rails receive a 1-colored ring.
            for rr in range(h):
                if g[rr][c] == 0:
                    g[rr][c] = 1
            for target_r in row_rails:
                if target_r == r:
                    continue
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        rr, cc = target_r + dr, c + dc
                        if 0 <= rr < h and 0 <= cc < w and (dr, dc) != (0, 0):
                            g[rr][cc] = 1
    return g
